PAYLOAD = ''

def sha(path):
    h = hashlib.sha256()
    with path.open('rb') as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b''):
            h.update(chunk)
    return h.hexdigest()

def validate(path, expected):
    with zipfile.ZipFile(path) as jar:
        names = jar.namelist()
        if len(names) != len(set(names)) or set(names) != set(expected):
            raise RuntimeError('El contenido del JAR no coincide con el parche.')
        if jar.testzip() is not None:
            raise RuntimeError('JAR dañado.')
        for name, digest in expected.items():
            if hashlib.sha256(jar.read(name)).hexdigest() != digest:
                raise RuntimeError('Verificación fallida: ' + name)

def main():
    mods = Path(__file__).resolve().parent
    if mods.name.lower() != 'mods':
        raise RuntimeError('Pon este archivo Python dentro de la carpeta mods y ejecútalo allí.')
    candidates = [p for p in mods.glob('*.jar') if p.name.lower().startswith(('firstaid', 'lesraisins'))]
    matches = []
    completed = []
    for spec in SPEC:
        found = []
        already = []
        for path in candidates:
            if sha(path) == spec['original']:
                found.append(path)
            elif path.name.lower().startswith(('firstaid', 'lesraisins')):
                try:
                    validate(path, spec['entries'])
                    already.append(path)
                except (RuntimeError, zipfile.BadZipFile, KeyError):
                    pass
        if len(found) + len(already) > 1:
            raise RuntimeError('Hay copias duplicadas de ' + spec['label'] + '. Retira los duplicados antes de ejecutar.')
        if already:
            completed.append(already[0])
        elif len(found) == 1:
            matches.append((spec, found[0]))
        else:
            raise RuntimeError('No encuentro la versión exacta de ' + spec['label'] + '. No se ha reemplazado ningún archivo.')
    if not matches:
        print('Los dos mods ya tienen este parche. No hace falta volver a aplicarlo.')
        return
    stamp = datetime.datetime.now().strftime('%Y%m%d-%H%M%S-%f')
    backup = mods.parent / 'copias_firstaid_lr' / stamp
    with tempfile.TemporaryDirectory(prefix='firstaid-lr-', dir=str(mods.parent)) as temporary:
        staged = []
        with zipfile.ZipFile(io.BytesIO(base64.b64decode(PAYLOAD))) as patch:
            for spec, path in matches:
                target = Path(temporary) / path.name
                with zipfile.ZipFile(path) as original, zipfile.ZipFile(target, 'w', zipfile.ZIP_DEFLATED) as result:
                    for name in spec['entries']:
                        data = patch.read(spec['prefix'] + name) if name in spec['changed'] else original.read(name)
                        result.writestr(name, data)
                validate(target, spec['entries'])
                staged.append((path, target))
        backup.mkdir(parents=True)
        for path, target in staged:
            shutil.copy2(path, backup / (path.name + '.bak'))
            if sha(backup / (path.name + '.bak')) != sha(path):
                raise RuntimeError('No se pudo verificar la copia de seguridad. No se ha reemplazado ningún archivo.')
        installed = []
        try:
            for path, target in staged:
                os.replace(target, path)
                installed.append(path)
        except BaseException:
            for path in installed:
                shutil.copy2(backup / (path.name + '.bak'), path)
            raise
    print('LISTO. First Aid y Les Raisins quedaron parcheados en mods.')
    print('Se conservaron los nombres de los JAR; no se añadieron duplicados.')
    print('Copias de seguridad: ' + str(backup))
    print('Ya puedes abrir Minecraft. La prueba dentro del juego sigue pendiente.')

if __name__ == '__main__':
    try:
        main()
    except Exception as error:
        print('ERROR: ' + str(error), file=sys.stderr)
        print('Cierra Minecraft antes de ejecutar este instalador.', file=sys.stderr)
        sys.exit(1)
